331	    /**
332	     * Computes the American Soundex code of a name: the retained first letter followed by up to
333	     * three digits encoding the remaining consonants ({@code B,F,P,V => 1}; {@code C,G,J,K,Q,S,X,Z
334	     * => 2}; {@code D,T => 3}; {@code L => 4}; {@code M,N => 5}; {@code R => 6}), with vowels and
335	     * {@code Y} acting as separators, {@code H} and {@code W} transparent (they do not break a run
336	     * of same-coded consonants), adjacent same-coded letters collapsed to a single digit, and the
337	     * code zero-padded to length 4. Non-letters are ignored. A {@code null} or letter-free name
338	     * yields the empty string. This is the single definition of the Soundex reduction shared by the
339	     * identity key ({@link #identityKey(String, String, String)}).
340	     *
341	     * @param name the name to encode, or {@code null}
342	     * @return the 4-character Soundex code, or the empty string when {@code name} has no letters
343	     */
344	    public static String soundex(String name) {
345	        if (name == null) {
346	            return "";
347	        }
348	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
349	        if (letters.isEmpty()) {
350	            return "";
351	        }
352	        StringBuilder code = new StringBuilder();
353	        code.append(letters.charAt(0));
354	        char previousCode = soundexCode(letters.charAt(0));
355	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
356	            char c = letters.charAt(i);
357	            if (c == 'H' || c == 'W') {
358	                continue;
359	            }
360	            char digit = soundexCode(c);
361	            if (digit != '0' && digit != previousCode) {
362	                code.append(digit);
363	            }
364	            previousCode = digit;
365	        }
366	        while (code.length() < 4) {
367	            code.append('0');
368	        }
369	        return code.toString();
370	    }
371	
372	    /**
373	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for a vowel, {@code Y},
374	     * {@code H} or {@code W} (the letters that do not contribute a digit). See
375	     * {@link #soundex(String)} for the digit groups.
376	     *
377	     * @param c the upper-case letter to encode
378	     * @return the Soundex digit {@code '1'}-{@code '6'}, or {@code '0'} when the letter contributes none
379	     */
380	    private static char soundexCode(char c) {
381	        switch (c) {
382	            case 'B': case 'F': case 'P': case 'V':
383	                return '1';
384	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
385	                return '2';
386	            case 'D': case 'T':
387	                return '3';
388	            case 'L':
389	                return '4';
390	            case 'M': case 'N':
391	                return '5';
392	            case 'R':
393	                return '6';
394	            default:
395	                return '0';
396	        }
397	    }
398	
399	    /**
400	     * Computes the full lower-case hex SHA-256 digest of a string: the input is hashed as UTF-8
401	     * bytes and each of the 32 digest bytes is rendered as two lower-case hex digits, yielding a
402	     * 64-character string. This is the single definition of the SHA-256 hex derivation shared by
403	     * every rule that hashes owner fields (for example the customer code and household identifier,
404	     * each formed from the leading upper-case characters of this digest). SHA-256 is a required
405	     * platform algorithm; were it ever unavailable an {@link IllegalStateException} is thrown.
406	     *
407	     * @param input the string to hash
408	     * @return the 64-character lower-case hex SHA-256 digest of {@code input}
409	     */
410	    public static String sha256Hex(String input) {
411	        try {
412	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
413	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
414	            StringBuilder sb = new StringBuilder(digest.length * 2);
415	            for (byte b : digest) {
416	                sb.append(String.format("%02x", b));
417	            }
418	            return sb.toString();
419	        }
420	        catch (java.security.NoSuchAlgorithmException e) {
421	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
422	        }
423	    }
