425	    /**
426	     * Fixed telephone country-code table: the exact national-number length (the count of digits
427	     * following the country code) each country code this application recognizes admits
428	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
429	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
430	     */
431	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
432	
433	    /**
434	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
435	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
436	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
437	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
438	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
439	     * no recognized country code. This is the single definition of how an E.164 telephone splits
440	     * from its country code, shared by every rule that reasons about a telephone's country code.
441	     *
442	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
443	     * @return the recognized country-code digits, or {@code null} when none is recognized
444	     */
445	    public static String countryCodeOf(String telephone) {
446	        if (telephone == null || !telephone.startsWith("+")) {
447	            return null;
448	        }
449	        String digits = telephone.substring(1);
450	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
451	            .filter(digits::startsWith)
452	            .max(Comparator.comparingInt(String::length))
453	            .orElse(null);
454	    }
455	
456	    /**
457	     * Resolves the exact national-number length (the count of digits following the country code) a
458	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
459	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
460	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
461	     * per-country length rule). This is the single definition of the per-country national-number
462	     * lengths, shared by every rule that relates a telephone's national number to its country code.
463	     *
464	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
465	     * @return the required national-number length, or {@code null} when the code is not recognized
466	     */
467	    public static Integer nationalNumberLength(String countryCode) {
468	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
469	    }
