471	    /**
472	     * Fixed city-to-region table: the canonical region each known city belongs to
473	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
474	     * absent from this table has no known region.
475	     */
476	    private static final Map<String, String> CITY_REGIONS = Map.of(
477	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
478	
479	    /**
480	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
481	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
482	     * region string, or {@code null} when the city has no known region. This is the single
483	     * definition of the city-to-region mapping, shared by every rule that derives a region
484	     * from an owner's city.
485	     *
486	     * @param city the city to resolve
487	     * @return the canonical region, or {@code null} when the city has no known region
488	     */
489	    public static String regionForCity(String city) {
490	        return CITY_REGIONS.get(city);
491	    }
492	
493	    /**
494	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
495	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
496	     * A region absent from this table has no fixed range.
497	     */
498	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
499	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
500	
501	    /**
502	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
503	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
504	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
505	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
506	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
507	     *
508	     * @param region the region to resolve, or {@code null}
509	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
510	     */
511	    public static int[] postcodeRangeForRegion(String region) {
512	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
513	    }
514	
515	    /**
516	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
517	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
518	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
519	     * value, or falls in no known range. This is the single definition of the postcode-to-region
520	     * mapping, shared by every rule that derives a region from a postcode.
521	     *
522	     * @param postcode the postcode to resolve
523	     * @return the canonical region, or {@code null} when the postcode maps to no known region
524	     */
525	    public static String regionForPostcode(String postcode) {
526	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
527	            return null;
528	        }
529	        int value = Integer.parseInt(postcode);
530	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
531	            int[] range = entry.getValue();
532	            if (value >= range[0] && value <= range[1]) {
533	                return entry.getKey();
534	            }
535	        }
536	        return null;
537	    }
538	
539	    /**
540	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
541	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
542	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
543	     * range does derivation fall back to the fixed city-to-region table (see
544	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
545	     * resolves to a known region. This is the single definition of an owner's region, shared by
546	     * every rule that derives a region from an owner.
547	     *
548	     * @return the owner's canonical region, or {@code null} when it has no known region
549	     */
550	    @Transient
551	    public String getRegion() {
552	        String region = regionForPostcode(this.postcode);
553	        return region != null ? region : regionForCity(this.city);
554	    }
