556	    /**
557	     * Resolves whether an {@code email} counts as present for membership purposes: the value is
558	     * non-null and not blank. Returns {@code false} otherwise. This is the single definition of an
559	     * owner "having an email", shared by every rule that turns email presence into a derived value
560	     * (its membership factor and its {@code contactPreference}).
561	     *
562	     * @param email the owner's email, or {@code null}
563	     * @return {@code true} when the email is present and not blank
564	     */
565	    public static boolean hasEmail(String email) {
