569	    /**
570	     * Resolves whether an owner with the given {@code namesakeCount} has no namesakes: the count is
571	     * present and equal to {@code 0}. Returns {@code false} when the count is {@code null} (unknown)
572	     * or positive. This is the single definition of the "no namesakes" membership factor, shared by
573	     * every rule that rewards an owner for being unique by name.
574	     *
575	     * @param namesakeCount the owner's namesake count, or {@code null}
576	     * @return {@code true} when the owner is known to have no namesakes
577	     */
578	    public static boolean hasNoNamesakes(Integer namesakeCount) {
579	        return namesakeCount != null && namesakeCount == 0;
580	    }
