582	    /**
583	     * Resolves the fiscal year a date falls in. The fiscal year starts on 1 July, so a date in July
584	     * through December belongs to the fiscal year of the following calendar year, while a date in
585	     * January through June belongs to the fiscal year of its own calendar year (for example both
586	     * 2025-08-01 and 2026-03-01 fall in fiscal year 2026). This is the single definition of the
587	     * date-to-fiscal-year mapping, shared by every value derived on a fiscal-year basis (the
588	     * {@code fiscalYear}, the membership number's year segment and tenure).
589	     *
590	     * @param date the date to resolve, never {@code null}
591	     * @return the fiscal year the date falls in
592	     */
593	    public static int fiscalYearOf(LocalDate date) {
594	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
595	    }
596	
597	    /**
598	     * Resolves whether an owner registered on {@code registrationDate} has long tenure as of
599	     * {@code asOf}: the number of elapsed fiscal years between the two dates (see
600	     * {@link #fiscalYearOf(LocalDate)}) exceeds {@code 1}. Returns {@code false} when
601	     * {@code registrationDate} is absent, so the owner has no derivable tenure; because a newly
602	     * created owner has zero elapsed fiscal years, it never counts as long-tenured. This is the
603	     * single definition of the "long tenure" membership factor, shared by every rule that rewards
604	     * an owner for tenure beyond a fiscal year.
605	     *
606	     * @param registrationDate the owner's registration date, or {@code null}
607	     * @param asOf the date the tenure is measured against
608	     * @return {@code true} when the owner's tenure exceeds one elapsed fiscal year
609	     */
610	    public static boolean hasLongTenure(LocalDate registrationDate, LocalDate asOf) {
611	        return registrationDate != null && fiscalYearOf(asOf) - fiscalYearOf(registrationDate) > 1;
612	    }
613	
614	    /**
615	     * Resolves whether an owner with the given {@code householdMemberCount} belongs to a large
616	     * household: the count is present and at least {@code 3}. Returns {@code false} when the count is
617	     * {@code null} (unknown) or smaller. This is the single definition of the "large household"
618	     * membership factor, shared by every rule that rewards an owner for a household of three or more.
619	     *
620	     * @param householdMemberCount the number of owners sharing the household, or {@code null}
621	     * @return {@code true} when the owner is known to belong to a household of three or more
622	     */
623	    public static boolean hasLargeHousehold(Integer householdMemberCount) {
624	        return householdMemberCount != null && householdMemberCount >= 3;
625	    }
626	
627	    /**
628	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
629	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
630	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
631	     * {@code 3} when the owner's tenure exceeds one elapsed fiscal year. Because a newly created
632	     * owner has zero tenure, the tenure points are never awarded on creation. This is the single source the
633	     * membership level is derived from (see {@link #getMembershipLevel()}).
634	     *
635	     * @return the owner's membership points
636	     */
637	    @Transient
638	    public Integer getMembershipPoints() {
639	        LocalDate today = LocalDate.now();
640	        int points = 0;
641	        if (hasEmail(this.email)) {
642	            points += 2;
643	        }
644	        if (hasNoNamesakes(this.namesakeCount)) {
645	            points += 1;
646	        }
647	        if (hasLargeHousehold(this.householdMemberCount)) {
648	            points += 2;
649	        }
650	        if (hasLongTenure(this.registrationDate, today)) {
651	            points += 3;
652	        }
653	        return points;
654	    }
655	
656	    /**
657	     * Resolves the numeric membership level a given number of membership points earns: {@code 1} for
658	     * {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for
659	     * {@code 6} or more points. This is the single definition of the points-to-level mapping, shared
660	     * by every rule that derives a membership level from points (see {@link #getMembershipLevel()}).
661	     *
662	     * @param points the membership points to map
663	     * @return the membership level those points earn
664	     */
665	    public static int membershipLevelForPoints(int points) {
666	        if (points >= 6) {
667	            return 4;
668	        }
669	        if (points >= 4) {
670	            return 3;
671	        }
672	        if (points >= 2) {
673	            return 2;
674	        }
675	        return 1;
676	    }
677	
678	    /**
679	     * Applies an owner's household level ceiling to a membership level: the level is returned
680	     * unchanged when {@code cap} is {@code null} (no ceiling applies), otherwise it is capped at
681	     * {@code cap} so it can never exceed it. This is the single definition of how the household
682	     * level ceiling caps a membership level, shared by every rule that reads a capped membership
683	     * level (see {@link #getMembershipLevel()}).
684	     *
685	     * @param level the uncapped membership level derived from the owner's points
686	     * @param cap the owner's household level ceiling, or {@code null} when no ceiling applies
687	     * @return the membership level after applying the ceiling
688	     */
689	    public static int cappedMembershipLevel(int level, Integer cap) {
690	        return cap == null ? level : Math.min(level, cap);
691	    }
692	
693	    /**
694	     * Returns this owner's numeric membership level, derived from its membership points (see
695	     * {@link #getMembershipPoints()}) by the single points-to-level mapping (see
696	     * {@link #membershipLevelForPoints(int)}): {@code 1} for {@code 0-1} points, {@code 2} for
697	     * {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more points. The
698	     * result is then held to the owner's household level ceiling {@code membershipLevelCap} (see
699	     * {@link #cappedMembershipLevel(int, Integer)}): a new owner joining a household may earn a
700	     * level at most one above the highest level among its existing household members, and no
701	     * ceiling applies when the owner joined an empty household.
702	     *
703	     * @return the owner's membership level, capped by its household level ceiling
704	     */
705	    @Transient
706	    public Integer getMembershipLevel() {
707	        return cappedMembershipLevel(membershipLevelForPoints(getMembershipPoints()), this.membershipLevelCap);
708	    }
709	
710	    /**
711	     * Returns this owner's fiscal year formatted as {@code 'FY<YY>'}, where YY is the last two digits
712	     * of the fiscal year (starting 1 July, see {@link #fiscalYearOf(LocalDate)}) the owner's
713	     * business-day-adjusted {@code registrationDate} falls in, e.g. {@code 'FY26'}. Returns
714	     * {@code null} when the owner has no registration date, so the fiscal year cannot be derived.
715	     * This is the single definition of an owner's fiscal year, shared by every value derived on a
716	     * fiscal-year basis (see {@link #getMembershipNumber()}).
717	     *
718	     * @return the owner's fiscal year, or {@code null} when it cannot be derived
719	     */
720	    @Transient
721	    public String getFiscalYear() {
722	        if (this.registrationDate == null) {
723	            return null;
724	        }
725	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
726	    }
727	
728	    /**
729	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
730	     * the last two digits of the fiscal year (see {@link #fiscalYearOf(LocalDate)}) the owner's
731	     * business-day-adjusted {@code registrationDate} falls in, e.g. {@code 'NSW-A1B2C3D4-M26'}.
732	     * Returns {@code null} when the owner has no customer code or registration date.
733	     *
734	     * @return the owner's membership number, or {@code null} when it cannot be derived
735	     */
736	    @Transient
737	    public String getMembershipNumber() {
738	        if (this.customerCode == null || this.registrationDate == null) {
739	            return null;
740	        }
741	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
742	    }
743	
744	    /**
745	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
746	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
747	     *
748	     * @return the owner's check digit, or {@code null} when it has no customer code
749	     */
750	    @Transient
751	    public Integer getCheckDigit() {
752	        if (this.customerCode == null) {
753	            return null;
754	        }
755	        String code = this.customerCode;
756	        int sum = 0;
757	        boolean dbl = true;
758	        for (int i = code.length() - 1; i >= 0; i--) {
759	            char c = code.charAt(i);
760	            if (c < '0' || c > '9') {
761	                continue;
762	            }
763	            int d = c - '0';
764	            if (dbl) {
765	                d *= 2;
766	                if (d > 9) {
767	                    d -= 9;
768	                }
769	            }
770	            sum += d;
771	            dbl = !dbl;
772	        }
773	        return (10 - (sum % 10)) % 10;
774	    }
775	
776	    /**
777	     * Returns this owner's age band, derived from {@code birthDate} computed against
778	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
779	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
780	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
781	     * band cannot be derived. This is the single definition of an owner's age band.
782	     *
783	     * @return the owner's age band, or {@code null} when it cannot be derived
784	     */
785	    @Transient
786	    public String getAgeBand() {
787	        if (this.birthDate == null || this.registrationDate == null) {
788	            return null;
789	        }
790	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
791	        if (age < 18) {
792	            return "MINOR";
793	        }
794	        if (age < 65) {
795	            return "ADULT";
796	        }
797	        return "SENIOR";
798	    }
799	
800	    protected Set<Pet> getPetsInternal() {
801	        if (this.pets == null) {
802	            this.pets = new HashSet<>();
803	        }
804	        return this.pets;
805	    }
806	
807	    protected void setPetsInternal(Set<Pet> pets) {
808	        this.pets = pets;
809	    }
810	
811	    public List<Pet> getPets() {
812	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
813	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
814	        return Collections.unmodifiableList(sortedPets);
815	    }
816	
817	    public void setPets(List<Pet> pets) {
818	        this.pets = new HashSet<>(pets);
819	    }
820	
821	    public void addPet(Pet pet) {
822	        getPetsInternal().add(pet);
823	        pet.setOwner(this);
824	    }
825	
826	    /**
827	     * Return the Pet with the given name, or null if none found for this Owner.
828	     *
829	     * @param name to test
830	     * @return true if pet name is already in use
831	     */
832	    public Pet getPet(String name) {
833	        return getPet(name, false);
834	    }
835	
836	    /**
837	     * Return the Pet with the given name, or null if none found for this Owner.
838	     *
839	     * @param name to test
840	     * @return true if pet name is already in use
841	     */
842	    public Pet getPet(String name, boolean ignoreNew) {
843	        name = name.toLowerCase();
844	        for (Pet pet : getPetsInternal()) {
845	            if (!ignoreNew || !pet.isNew()) {
846	                String compName = pet.getName();
847	                compName = compName.toLowerCase();
848	                if (compName.equals(name)) {
849	                    return pet;
850	                }
851	            }
852	        }
853	        return null;
854	    }
855	
856	    public Pet getPet(Integer petId) {
857	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
858	    }
859	
860	    @Override
861	    public String toString() {
862	        return new ToStringCreator(this)
863	
864	            .append("id", this.getId())
865	            .append("new", this.isNew())
866	            .append("lastName", this.getLastName())
867	            .append("firstName", this.getFirstName())
868	            .append("address", this.address)
869	            .append("city", this.city)
870	            .append("telephone", this.telephone)
871	            .append("email", this.email)
872	            .toString();
873	    }
874	}
