233	    /**
234	     * Emits the immutable, structured {@code OWNER_CREATED} audit event for a freshly persisted owner,
235	     * alongside the human-readable audit line. The event is a JSON object carrying, in order, a
236	     * {@code seq} (a monotonically increasing integer across creates, see {@link #OWNER_CREATED_SEQ}),
237	     * the owner's {@code ownerId}, the owner's current primary identifier (see
238	     * {@link #primaryIdentifier(Owner)}) under the {@code customerCode} key, the owner's derived
239	     * {@code membershipLevel}, and the {@code event} marker {@code 'OWNER_CREATED'}. Published to the
240	     * dedicated {@code AUDIT} logger so downstream consumers can react to owner creation structurally
241	     * rather than by parsing the free-form line.
242	     *
243	     * @param owner the persisted owner, already carrying its generated id and derived values
244	     */
245	    private void emitOwnerCreatedEvent(Owner owner) {
246	        long seq = OWNER_CREATED_SEQ.incrementAndGet();
247	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"customerCode\":{},\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
248	            seq, owner.getId(), jsonString(primaryIdentifier(owner)), owner.getMembershipLevel());
249	    }
