265	    /**
266	     * Renders a value as a JSON string literal for the structured audit event: {@code null} becomes
267	     * the JSON {@code null} keyword, otherwise the value is quoted with the JSON-significant
268	     * characters ({@code "} and {@code \}) escaped. The derived identifiers this carries never contain
269	     * such characters, but escaping keeps the emitted event valid JSON regardless.
270	     *
271	     * @param value the value to render, or {@code null}
272	     * @return the JSON representation of the value
273	     */
274	    private String jsonString(String value) {
275	        if (value == null) {
276	            return "null";
277	        }
278	        return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
279	    }
