431	    /**
432	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
433	     * The address is normalized in place (so a required-field check that follows rejects an
434	     * address blank after normalization), the required fields are checked, the telephone and
435	     * email are normalized in place, and the resulting owner is rejected when its derived
436	     * identity key already belongs to another owner. Each rule
437	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
438	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
439	     * to be mapped and saved.
440	     *
441	     * @param ownerFieldsDto the submitted owner fields, normalized in place
442	     */
443	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
444	        applyAddress(ownerFieldsDto);
445	        validateRequiredFields(ownerFieldsDto);
446	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
447	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
448	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
449	        rejectDuplicateIdentity(ownerFieldsDto);
450	        rejectCityAtCapacity(ownerFieldsDto.getCity());
451	        rejectDailyLimitExceeded(registrationDate);
452	    }
