454	    /**
455	     * Applies an owner's address to the submitted fields, normalizing it in place into the
456	     * canonical form stored and returned for the owner. This is the single intake step that owns
457	     * how a submitted address becomes an owner's stored address: it delegates every transform to
458	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
459	     * the results back onto {@code ownerFieldsDto}.
460	     *
461	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
462	     * is present the two structured lines are normalized in place and the flat {@code address} is
463	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
464	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
465	     * every rule that later reads {@code address} sees the structured value. When no structured
466	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
467	     * backward compatibility.
468	     *
469	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
470	     * blank after normalization in either form is rejected by the required-field check that
471	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
472	     * list of named intake steps and gives address handling one place to grow.
473	     *
474	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
475	     */
476	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
477	        String line1 = ownerFieldsDto.getAddressLine1();
478	        if (line1 != null && !line1.isBlank()) {
479	            String normalizedLine1 = normalizeAddress(line1);
480	            ownerFieldsDto.setAddressLine1(normalizedLine1);
481	            String line2 = ownerFieldsDto.getAddressLine2();
482	            if (line2 != null && !line2.isBlank()) {
483	                String normalizedLine2 = normalizeAddress(line2);
484	                ownerFieldsDto.setAddressLine2(normalizedLine2);
485	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
486	            } else {
487	                ownerFieldsDto.setAddressLine2(null);
488	                ownerFieldsDto.setAddress(normalizedLine1);
489	            }
490	        } else {
491	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
492	        }
493	    }
