495	    /**
496	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
497	     * falls on a business day. The date supplied on the request is used when present, otherwise the
498	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
499	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
500	     * is left unchanged. This single adjusted date
501	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
502	     * membership number's year segment, the per-day create limit) is computed against.
503	     *
504	     * A supplied registration date later than the server's current date is rejected with an
505	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
506	     *
507	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
508	     * @return the effective registration date rolled forward to the next business day
509	     */
510	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
511	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
512	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
513	            throw new InvalidFieldsException(List.of("registrationDate"));
514	        }
515	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
516	        return toBusinessDay(effective);
517	    }
518	
519	    /**
520	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
521	     * advanced, along with weekends, until it reaches the next non-holiday business day.
522	     */
523	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
524	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
525	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
526	        LocalDate.parse("2026-12-28"));
527	
528	    /**
529	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
530	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
531	     * date already on such a business day is returned unchanged.
532	     *
533	     * @param date the date to adjust
534	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
535	     */
536	    private LocalDate toBusinessDay(LocalDate date) {
537	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
538	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
539	                || PUBLIC_HOLIDAYS.contains(date)) {
540	            date = date.plusDays(1);
541	        }
542	        return date;
543	    }
