545	    /**
546	     * The maximum number of owners that may be created on a single day. Once this many owners
547	     * already carry today's {@code registrationDate}, no further owner may be created today.
548	     */
549	    private static final long DAILY_OWNER_LIMIT = 100L;
550	
551	    /**
552	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
553	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
554	     * date the new owner would be stored with, so owners are capped per business day. When the limit
555	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
556	     * advice renders as a 429 Too Many Requests response.
557	     *
558	     * @param registrationDate the adjusted business-day registration date of the owner being created
559	     */
560	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
561	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
562	            throw new DailyOwnerLimitExceededException(registrationDate);
563	        }
564	    }
