566	    /**
567	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
568	     * given date. This is the single definition of the per-day owner count, shared by the per-day
569	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
570	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
571	     *
572	     * @param registrationDate the adjusted business-day registration date to count owners against
573	     * @return the number of existing owners carrying that registration date
574	     */
575	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
576	        return this.clinicService.findAllOwners().stream()
577	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
578	            .count();
579	    }
