581	    /**
582	     * The number of owners that may carry a single day's {@code registrationDate} before that day
583	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
584	     * the create and read responses report {@code bulkSignupWarning} true for that date.
585	     */
586	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
587	
588	    /**
589	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
590	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
591	     * count is taken against the same adjusted date owners are stored with, mirroring the
592	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
593	     *
594	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
595	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
596	     */
597	    private boolean bulkSignupWarning(LocalDate registrationDate) {
598	        if (registrationDate == null) {
599	            return false;
600	        }
601	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
602	    }
