604	    /**
605	     * The maximum number of owners a single city may hold. Once a city already contains this
606	     * many owners, no further owner may be created in it.
607	     */
608	    private static final long CITY_OWNER_CAPACITY = 50L;
609	
610	    /**
611	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
612	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
613	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
614	     * which the exception advice renders as a 409 Conflict response.
615	     *
616	     * @param city the city of the owner being created
617	     */
618	    private void rejectCityAtCapacity(String city) {
619	        if (countOwnersInCity(city) >= CITY_OWNER_CAPACITY) {
620	            throw new CityCapacityExceededException(city);
621	        }
622	    }
