624	    /**
625	     * Counts the existing owners whose {@code city} equals the given city, compared
626	     * case-insensitively. This is the single definition of the per-city owner count, shared by the
627	     * hard capacity rejection ({@link #rejectCityAtCapacity(String)}) and the approaching-capacity
628	     * warning ({@link #capacityWarning(String)}), so both measure a city's occupancy identically.
629	     *
630	     * @param city the city to count owners against
631	     * @return the number of existing owners whose city matches
632	     */
633	    private long countOwnersInCity(String city) {
634	        return this.clinicService.findAllOwners().stream()
635	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
636	            .count();
637	    }
