664	    /**
665	     * Builds the customer code assigned to a newly created owner. The code is formatted as
666	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
667	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
668	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
669	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
670	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
671	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
672	     * identity scheme needs.
673	     *
674	     * @param owner the owner being created, whose fields the code is derived from
675	     * @return the formatted customer code
676	     */
677	    private String customerCodeFor(Owner owner) {
678	        String region = owner.getRegion();
679	        String regionCode = region != null ? region : "UNKNOWN";
680	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
681	        return deduplicateCustomerCode(regionCode + "-" + hash8);
682	    }
