684	    /**
685	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
686	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
687	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
688	     *
689	     * @param baseCode the customer code computed for the owner being created
690	     * @return the base code when it is already unique, otherwise the de-duplicated code
691	     */
692	    private String deduplicateCustomerCode(String baseCode) {
693	        Set<String> existing = this.clinicService.findAllOwners().stream()
694	            .map(Owner::getCustomerCode)
695	            .filter(Objects::nonNull)
696	            .collect(Collectors.toSet());
697	        if (!existing.contains(baseCode)) {
698	            return baseCode;
699	        }
700	        int n = 2;
701	        while (existing.contains(baseCode + "-" + n)) {
702	            n++;
703	        }
704	        return baseCode + "-" + n;
705	    }
