752	    /**
753	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
754	     * duplicate: a non-deleted owner whose {@code lastName} shares the new owner's Soundex code (see
755	     * {@link Owner#soundex(String)}) and whose {@code postcode} matches, while carrying a different
756	     * identity key (see {@link Owner#identityKey(String, String, String)}). Requiring a differing
757	     * identity key keeps a hard duplicate — already rejected with 409 by
758	     * {@link #rejectDuplicateIdentity(OwnerFieldsDto)} — from also being flagged as a soft match, so
759	     * the two household members whose telephones differ (hence differing identity keys, but matching
760	     * Soundex and postcode) are exactly the soft matches surfaced here. This is the single definition
761	     * of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records
762	     * the outcome on the owner. An owner without a postcode can share no postcode and matches nothing,
763	     * so {@link java.util.Optional#empty()} is returned.
764	     *
765	     * @param owner the owner being created, already carrying its normalized telephone and postcode
766	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
767	     */
768	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
769	        if (owner.getPostcode() == null) {
770	            return java.util.Optional.empty();
771	        }
772	        String soundex = Owner.soundex(owner.getLastName());
773	        String identityKey = owner.getIdentityKey();
774	        return this.clinicService.findAllOwners().stream()
775	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
776	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
777	                && soundex.equals(Owner.soundex(existing.getLastName()))
778	                && owner.getPostcode().equals(existing.getPostcode()))
779	            .findFirst();
780	    }
