809	    /**
810	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
811	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
812	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
813	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
814	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
815	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
816	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
817	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
818	     *
819	     * @param telephone the submitted telephone value
820	     * @return the normalized E.164 telephone
821	     */
822	    private String normalizeTelephone(String telephone) {
823	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
824	        String e164;
825	        if (cleaned.startsWith("+")) {
826	            e164 = "+" + cleaned.substring(1);
827	        } else {
828	            String national = cleaned;
829	            if (national.startsWith("0")) {
830	                national = national.substring(1);
831	            }
832	            e164 = "+61" + national;
833	        }
834	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
835	            throw new InvalidFieldsException(List.of("telephone"));
836	        }
837	        validateNationalNumberLength(e164);
838	        return e164;
839	    }
