841	    /**
842	     * Validates the national-number length of an already syntactically valid E.164 telephone
843	     * against its country code. When the number carries a country code this application recognizes
844	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
845	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
846	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
847	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
848	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
849	     * that is not recognized carries no per-country length rule and is left to the general
850	     * 8-to-15-digit E.164 check.
851	     *
852	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
853	     */
854	    private void validateNationalNumberLength(String e164) {
855	        String countryCode = Owner.countryCodeOf(e164);
856	        if (countryCode == null) {
857	            return;
858	        }
859	        int nationalLength = e164.length() - 1 - countryCode.length();
860	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
861	            throw new InvalidFieldsException(List.of("telephone"));
862	        }
863	    }
