865	    /**
866	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
867	     * and a domain containing at least one dot, none of the parts holding whitespace or a
868	     * second {@code @}.
869	     */
870	    private static final java.util.regex.Pattern EMAIL_PATTERN =
871	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
872	
873	    /**
874	     * Disposable email domains an owner may not register with. An email whose domain (compared
875	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
876	     */
877	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
878	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
879	
880	    /**
881	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
882	     * accepted and returned unchanged. When present it must be a syntactically valid address
883	     * whose domain is not on the disposable-domain blocklist (see
884	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
885	     * present but syntactically invalid or on a disposable domain an
886	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
887	     * response naming the {@code email} field.
888	     *
889	     * @param email the submitted email value, or {@code null} when omitted
890	     * @return the lower-cased email, or {@code null} when none was supplied
891	     */
892	    private String normalizeEmail(String email) {
893	        if (email == null) {
894	            return null;
895	        }
896	        String trimmed = email.trim();
897	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
898	            throw new InvalidFieldsException(List.of("email"));
899	        }
900	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
901	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
902	            throw new InvalidFieldsException(List.of("email"));
903	        }
904	        return canonicalEmail(trimmed);
905	    }
