907	    /**
908	     * Reduces an email to the canonical form used both to store it and to compare it against
909	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
910	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
911	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
912	     * value read back off an existing owner without risk of rejecting it. This is the single
913	     * definition of email identity: two emails denote the same address exactly when they
914	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
915	     * an email already on an existing owner can be compared for equality after both pass through
916	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
917	     *
918	     * @param email the email to canonicalize, or {@code null} when none was supplied
919	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
920	     */
921	    private String canonicalEmail(String email) {
922	        if (email == null) {
923	            return null;
924	        }
925	        return email.trim().toLowerCase(java.util.Locale.ROOT);
926	    }
