928	    /**
929	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
930	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
931	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
932	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
933	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
934	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
935	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
936	     * 400 response naming the {@code postcode} field.
937	     *
938	     * @param postcode the submitted postcode, or {@code null} when omitted
939	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
940	     */
941	    private void validatePostcode(String postcode, String city) {
942	        if (postcode == null) {
943	            return;
944	        }
945	        if (!postcode.matches("^[0-9]{4}$")) {
946	            throw new InvalidFieldsException(List.of("postcode"));
947	        }
948	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
949	        if (range != null) {
950	            int value = Integer.parseInt(postcode);
951	            if (value < range[0] || value > range[1]) {
952	                throw new InvalidFieldsException(List.of("postcode"));
953	            }
954	        }
955	    }
