957	    /**
958	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
959	     * identity is its single derived identity key (see
960	     * {@link Owner#identityKey(String, String, String)}) — the SHA-256 hex digest over its
961	     * normalized {@code telephone}, canonical {@code email} and the Soundex code of its
962	     * {@code lastName} — so a new owner is a hard duplicate only when some existing, non-deleted
963	     * owner carries the same identity key. The email-domain blocklist has already been applied when
964	     * the email was normalized ahead of this check, so a disposable-domain email is rejected before
965	     * duplicate detection runs. Two owners that merely belong to the same household (the same last
966	     * name and postcode) but carry different telephones now have distinct identity keys and are not
967	     * rejected here; such a near-match is instead recorded as a soft {@code possibleDuplicate} (see
968	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
969	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
970	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
971	     * deliberate household member and bypasses this block.
972	     *
973	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
974	     */
975	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
976	        if (sharesHousehold(ownerFieldsDto)) {
977	            return;
978	        }
979	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
980	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
981	        boolean taken = this.clinicService.findAllOwners().stream()
982	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
983	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
984	        if (taken) {
985	            throw new DuplicateIdentityException(identityKey);
986	        }
987	    }
