1124	     * identifier, or no existing member — no ceiling applies and {@code null} is returned, letting
1125	     * the owner earn its uncapped level (see {@link Owner#cappedMembershipLevel(int, Integer)}).
1126	     *
1127	     * @param householdId the shared household identifier of the owner being created, or {@code null}
1128	     * @return one above the household's current maximum membership level, or {@code null} when no ceiling applies
1129	     */
1130	    private Integer householdMembershipLevelCap(String householdId) {
1131	        java.util.OptionalInt max = householdMembers(householdId).stream()
1132	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1133	            .peek(this::applyHouseholdMemberCount)
1134	            .mapToInt(Owner::getMembershipLevel)
1135	            .max();
1136	        return max.isPresent() ? max.getAsInt() + 1 : null;
1137	    }
1138	
1139	    /**
1140	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1141	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1142	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1143	     *
1144	     * @param value the value to collapse, or {@code null}
1145	     * @return the whitespace-collapsed value, never {@code null}
1146	     */
1147	    private String collapseWhitespace(String value) {
1148	        if (value == null) {
1149	            return "";
1150	        }
1151	        return value.trim().replaceAll("\\s+", " ");
1152	    }
1153	
1154	    /**
1155	     * Common street-type abbreviations expanded during address normalization, keyed by their
1156	     * upper-cased token.
1157	     */
1158	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1159	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1160	
1161	    /**
1162	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1163	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1164	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1165	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1166	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1167	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1168	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1169	     * everywhere an address is stored or compared.
1170	     *
1171	     * @param address the submitted address value, or {@code null}
1172	     * @return the normalized address, never {@code null}
1173	     */
1174	    private String normalizeAddress(String address) {
1175	        if (address == null) {
1176	            return "";
1177	        }
1178	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1179	        if (collapsed.isEmpty()) {
1180	            return "";
1181	        }
1182	        String[] tokens = collapsed.split(" ");
1183	        StringBuilder sb = new StringBuilder(collapsed.length());
1184	        for (int i = 0; i < tokens.length; i++) {
1185	            if (i > 0) {
1186	                sb.append(' ');
1187	            }
1188	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1189	        }
1190	        return sb.toString();
1191	    }
1192	}
